// Stub hypervisor syscall implementations for kernel builds where
// //config:hypervisor=false.  Every entry point returns ZX_ERR_NOT_SUPPORTED
// so that userland callers receive a clear error without crashing.
//
// The stubs must match the signatures generated by syscalls.cc's dispatch
// macros (see lib/syscalls/forward.h for user_in_ptr / user_out_ptr wrappers).

#include <lib/syscalls/forward.h>
#include <zircon/errors.h>
#include <zircon/syscalls/hypervisor.h>
#include <zircon/types.h>

zx_status_t sys_guest_create(zx_handle_t /*resource*/, uint32_t /*options*/,
                             zx_handle_t* /*guest_handle*/, zx_handle_t* /*vmar_handle*/) {
  return ZX_ERR_NOT_SUPPORTED;
}

zx_status_t sys_guest_set_trap(zx_handle_t /*handle*/, uint32_t /*kind*/, zx_vaddr_t /*addr*/,
                               size_t /*size*/, zx_handle_t /*port_handle*/, uint64_t /*key*/) {
  return ZX_ERR_NOT_SUPPORTED;
}

zx_status_t sys_vcpu_create(zx_handle_t /*guest_handle*/, uint32_t /*options*/,
                            zx_vaddr_t /*entry*/, zx_handle_t* /*out*/) {
  return ZX_ERR_NOT_SUPPORTED;
}

zx_status_t sys_vcpu_enter(zx_handle_t /*handle*/,
                           user_out_ptr<zx_port_packet_t> /*user_packet*/) {
  return ZX_ERR_NOT_SUPPORTED;
}

zx_status_t sys_vcpu_kick(zx_handle_t /*handle*/) { return ZX_ERR_NOT_SUPPORTED; }

zx_status_t sys_vcpu_interrupt(zx_handle_t /*handle*/, uint32_t /*vector*/) {
  return ZX_ERR_NOT_SUPPORTED;
}

zx_status_t sys_vcpu_read_state(zx_handle_t /*handle*/, uint32_t /*kind*/,
                                user_out_ptr<void> /*user_buffer*/, size_t /*buffer_size*/) {
  return ZX_ERR_NOT_SUPPORTED;
}

zx_status_t sys_vcpu_write_state(zx_handle_t /*handle*/, uint32_t /*kind*/,
                                 user_in_ptr<const void> /*user_buffer*/,
                                 size_t /*buffer_size*/) {
  return ZX_ERR_NOT_SUPPORTED;
}
